"use strict";(self.webpackChunk_abdm_docs_site=self.webpackChunk_abdm_docs_site||[]).push([["19429"],{44933(e,i,t){t.r(i),t.d(i,{metadata:()=>n,default:()=>u,frontMatter:()=>c,contentTitle:()=>p,toc:()=>l,assets:()=>d});var n=JSON.parse('{"id":"nhcx/v1/api/registry/endpoints/registry-v2-participant-delink-abha-policy","title":"De-link ABHA policies (V2)","description":"V2 variant of the ABHA policy de-link; same ParticipantDeLinkAbhaRequest body and response as the unversioned call.","source":"@site/docs/nhcx/v1/api/registry/endpoints/registry-v2-participant-delink-abha-policy.mdx","sourceDirName":"nhcx/v1/api/registry/endpoints","slug":"/nhcx/v1/api/registry/endpoints/registry-v2-participant-delink-abha-policy","permalink":"/docs/pr-11/docs/nhcx/v1/api/registry/endpoints/registry-v2-participant-delink-abha-policy","draft":false,"unlisted":false,"tags":[],"version":"current","lastUpdatedAt":null,"frontMatter":{"title":"De-link ABHA policies (V2)","sidebar_label":"De-link ABHA policies (V2)","sidebar_class_name":"api-method api-method--post","description":"V2 variant of the ABHA policy de-link; same ParticipantDeLinkAbhaRequest body and response as the unversioned call.","hide_table_of_contents":true,"hide_title":true,"wrapperClassName":"api-doc","verification":"unverified","source":"nhcx-registry.yaml","generated":true},"sidebar":"nhcx-v1-api","previous":{"title":"De-link ABHA policies","permalink":"/docs/pr-11/docs/nhcx/v1/api/registry/endpoints/registry-participant-delink-abha-policy"},"next":{"title":"Get beneficiary policies","permalink":"/docs/pr-11/docs/nhcx/v1/api/registry/endpoints/registry-participant-get-policies"}}'),a=t(62540),r=t(43023),s=t(44136),o=JSON.parse('{"id":"registry_v2_participant_delink_abha_policy","module":"Participant registry","moduleId":"registry","kind":"operation","method":"POST","path":"/V2/participant/delink/abha/policy","server":"https://apisbx.abdm.gov.in/pmjay/sbxhcx/participanthcxservice","servers":[{"url":"https://apisbx.abdm.gov.in/pmjay/sbxhcx/participanthcxservice","description":"Sandbox, Participant service."},{"url":"https://apisprod.nha.gov.in/pmjay/hcx/participanthcxservice","description":"Production."}],"summary":"De-link ABHA policies (V2)","description":"V2 variant of the ABHA policy de-link; same ParticipantDeLinkAbhaRequest body and response as the unversioned call.\\n\\n### Business purpose\\n\\nThis endpoint performs the same member-layer removal as /participant/delink/abha/policy: it takes products out of a member\'s link for a given payer so that providers stop discovering lapsed or migrated coverage. The OpenAPI document exposes it as participantDeLinkAbhaPolicyV2 with an identical request and response schema; the documentation does not describe any behavioural difference beyond the path and operationId. It is the natural partner of /V2/participant/link/abha/policy for integrations that have standardised on the V2 paths.\\n\\n### When to use\\n\\nUse it in the same situations as the v1 de-link: policy termination, member removal, product migration, or as the first step when an insurer changes TPA (de-link, then link again with the new processingid). It is part of member-layer maintenance and is not tied to any claim workflow code. Pair it consistently with the V2 link and V2 get-policies calls.\\n\\n### Preconditions\\n\\n- A valid Bearer token from the client-credentials call (POST /get/session, form-urlencoded client_id, client_secret, grant_type=client_credentials); tokens last 1200 seconds, so refresh before expiry.\\n- HTTP headers Accept: application/json, Content-Type: application/json and bearer_auth: Bearer <token> (the participant service uses bearer_auth, not Authorization).\\n- Base path for the participant service: https://apisbx.abdm.gov.in/pmjay/sbxhcx/participanthcxservice (sandbox) or https://apisprod.nha.gov.in/pmjay/hcx/participanthcxservice (production).\\n- This is a synchronous plain-JSON registry call: no JWE envelope, no x-hcx-* protocol headers and no correlation id are involved.\\n- The caller must be the payerid or processingid participant from the original link, using a token minted with the client_id used at participant creation.\\n- Body: requestid (UUID), payerid, memberid and policies are required; processingid is optional; there is no abhanumber field.\\n- Note the capital V in /V2/.\\n\\n### Postconditions\\n\\nOn success the service returns HTTP 200 with ParticipantDeLinkAbhaResponse and the products are no longer visible through the get-policies endpoints for that payer and member. There is no callback. An unauthorised caller is refused with an error message, and a product that is not linked yields \\"There is no policies with requested details\\". Other errors use the 400/404/500 ErrorResponse envelope. Provider-side policy caches are documented as permanent, so they will keep the old answer until forced to refresh.\\n\\n### Common mistakes\\n\\n- Calling from a participant that is neither the payerid nor the processingid used at link time; NHCX checks the client id in the token, not the body, and refuses the call (common mistake 10).\\n- Listing a product that is not actually linked for that payerid and memberid, which returns the error message \\"There is no policies with requested details\\".\\n- Including abhanumber or mobilenumber in the body; the de-link request is keyed on payerid, memberid and the products listed, and has no ABHA field.\\n- Expecting provider-side caches to update: the handbook documents the policy cache as permanent with no TTL, so a de-linked policy keeps appearing until the provider passes forceRefresh: true.\\n- Using a token generated with a different client_id from the one used when the payer or TPA participant was created.\\n- Lower-casing the path; /v2/participant/delink/abha/policy is not a documented route.\\n\\n### Best practices\\n\\n- De-link only the specific products that need removing; the policies array is the unit of work.\\n- When moving an insurer to a new TPA, follow the documented order: de-link the existing policies, then link them again with the new TPA\'s participant code as processingid.\\n- Generate a fresh UUID for requestid on every call and log it with the response.\\n- Confirm the result with /participant/get/policies afterwards, and remember that providers may need a forced refresh of their own policy cache.\\n- Refresh the Bearer token proactively and retry once on 401 before escalating.\\n\\n### Related scenario\\n\\nA TPA is informed by one of its insurers that a corporate group policy has been cancelled mid-term. The TPA\'s system lists the affected members from its own records, calls /V2/participant/get/policies to confirm what NHCX currently holds, and then calls /V2/participant/delink/abha/policy per member with the insurer\'s participant code as payerid, its own code as processingid and the cancelled product. Each success is logged against the member. When a former member later presents at a hospital, the provider\'s policy lookup (after a forced cache refresh) no longer shows the product, and the desk proceeds as a self-pay case rather than submitting a coverage-eligibility check.\\n\\n### Specification\\n\\nChapter [Creating and updating a participant](/docs/nhcx/v1/getting-started/creating-and-updating-a-participant) of the NHCX integration specification.","security":[{"name":"bearerAuth","type":"http","scheme":"bearer","description":"On every NHCX call, the token goes in a header called `bearer_auth`, with the word `Bearer` and a space in front. The sources are not unanimous: the authentication page and the FAQ both write the example as `Authorization`, and the notification endpoint uses `Authorization`. The safe course, and what the adapter does, is to send both headers with the same value."}],"headers":[{"name":"bearer_auth","required":true,"description":"It is `bearer_auth`, not `Authorization`, on NHCX\'s own endpoints.","example":"Bearer <access token>","type":"string"}],"pathParams":[],"queryParams":[],"body":[{"name":"requestid","type":"string","required":false,"description":"","encrypted":false},{"name":"payerid","type":"string","required":false,"description":"","encrypted":false},{"name":"memberid","type":"string","required":false,"description":"","encrypted":false},{"name":"policies","type":"object[]","required":false,"description":"","encrypted":false},{"name":"policies.productid","type":"string","required":false,"description":"","encrypted":false},{"name":"policies.productname","type":"string","required":false,"description":"","encrypted":false},{"name":"processingid","type":"string","required":false,"description":"","encrypted":false}],"requestExample":{"requestid":"c4d2e1f0-8b7a-4c6d-9e5f-1a2b3c4d5e66","payerid":"100234@sbx","memberid":"MEM-2026-000123","policies":[{"productid":"PRD-INDIV-07","productname":"Individual Health Silver"}],"processingid":"100235@sbx"},"responses":[{"status":"200","description":"On success the service returns HTTP 200 with ParticipantDeLinkAbhaResponse and the products are no longer visible through the get-policies endpoints for that payer and member.","example":{"result":"success"}}],"tag":"Participant registry","tagDescription":"Every NHCX API call, whether a registry lookup, a certificate fetch or a claim submission, is rejected unless it carries a valid Bearer token, so this is the first call any integration makes and the first thing to check when a working integration starts failing.","curl":"curl --request POST \\\\\\n  --url https://apisbx.abdm.gov.in/pmjay/sbxhcx/participanthcxservice/V2/participant/delink/abha/policy \\\\\\n  --header \'Authorization: Bearer <ACCESS_TOKEN_FROM_SESSIONS_CALL>\' \\\\\\n  --header \'bearer_auth: Bearer <access token>\' \\\\\\n  --header \'Content-Type: application/json\' \\\\\\n  --data \'{\\n  \\"requestid\\": \\"c4d2e1f0-8b7a-4c6d-9e5f-1a2b3c4d5e66\\",\\n  \\"payerid\\": \\"100234@sbx\\",\\n  \\"memberid\\": \\"MEM-2026-000123\\",\\n  \\"policies\\": [\\n    {\\n      \\"productid\\": \\"PRD-INDIV-07\\",\\n      \\"productname\\": \\"Individual Health Silver\\"\\n    }\\n  ],\\n  \\"processingid\\": \\"100235@sbx\\"\\n}\'","samples":[{"id":"curl","label":"cURL","language":"bash","code":"curl --request POST \\\\\\n  --url https://apisbx.abdm.gov.in/pmjay/sbxhcx/participanthcxservice/V2/participant/delink/abha/policy \\\\\\n  --header \'Authorization: Bearer <ACCESS_TOKEN_FROM_SESSIONS_CALL>\' \\\\\\n  --header \'bearer_auth: Bearer <access token>\' \\\\\\n  --header \'Content-Type: application/json\' \\\\\\n  --data \'{\\n  \\"requestid\\": \\"c4d2e1f0-8b7a-4c6d-9e5f-1a2b3c4d5e66\\",\\n  \\"payerid\\": \\"100234@sbx\\",\\n  \\"memberid\\": \\"MEM-2026-000123\\",\\n  \\"policies\\": [\\n    {\\n      \\"productid\\": \\"PRD-INDIV-07\\",\\n      \\"productname\\": \\"Individual Health Silver\\"\\n    }\\n  ],\\n  \\"processingid\\": \\"100235@sbx\\"\\n}\'"},{"id":"python","label":"Python","language":"python","code":"import requests\\n\\nresponse = requests.post(\\n    \\"https://apisbx.abdm.gov.in/pmjay/sbxhcx/participanthcxservice/V2/participant/delink/abha/policy\\",\\n    headers={\\n        \\"Authorization\\": \\"Bearer <ACCESS_TOKEN_FROM_SESSIONS_CALL>\\",\\n        \\"bearer_auth\\": \\"Bearer <access token>\\",\\n        \\"Content-Type\\": \\"application/json\\",\\n    },\\n    json={\\n        \\"requestid\\": \\"c4d2e1f0-8b7a-4c6d-9e5f-1a2b3c4d5e66\\",\\n        \\"payerid\\": \\"100234@sbx\\",\\n        \\"memberid\\": \\"MEM-2026-000123\\",\\n        \\"policies\\": [\\n            {\\n                \\"productid\\": \\"PRD-INDIV-07\\",\\n                \\"productname\\": \\"Individual Health Silver\\"\\n            }\\n        ],\\n        \\"processingid\\": \\"100235@sbx\\"\\n    },\\n)\\n\\nprint(response.status_code, response.text)"},{"id":"node","label":"Node","language":"javascript","code":"const response = await fetch(\\"https://apisbx.abdm.gov.in/pmjay/sbxhcx/participanthcxservice/V2/participant/delink/abha/policy\\", {\\n  method: \\"POST\\",\\n  headers: {\\n    \\"Authorization\\": \\"Bearer <ACCESS_TOKEN_FROM_SESSIONS_CALL>\\",\\n    \\"bearer_auth\\": \\"Bearer <access token>\\",\\n    \\"Content-Type\\": \\"application/json\\",\\n  },\\n  body: JSON.stringify({\\n    \\"requestid\\": \\"c4d2e1f0-8b7a-4c6d-9e5f-1a2b3c4d5e66\\",\\n    \\"payerid\\": \\"100234@sbx\\",\\n    \\"memberid\\": \\"MEM-2026-000123\\",\\n    \\"policies\\": [\\n      {\\n        \\"productid\\": \\"PRD-INDIV-07\\",\\n        \\"productname\\": \\"Individual Health Silver\\"\\n      }\\n    ],\\n    \\"processingid\\": \\"100235@sbx\\"\\n  }),\\n});\\n\\nconsole.log(response.status, await response.text());"}]}');let c={title:"De-link ABHA policies (V2)",sidebar_label:"De-link ABHA policies (V2)",sidebar_class_name:"api-method api-method--post",description:"V2 variant of the ABHA policy de-link; same ParticipantDeLinkAbhaRequest body and response as the unversioned call.",hide_table_of_contents:!0,hide_title:!0,wrapperClassName:"api-doc",verification:"unverified",source:"nhcx-registry.yaml",generated:!0},p,d={},l=[];function h(e){return(0,a.jsx)(s.A,{operation:o})}function u(e={}){let{wrapper:i}={...(0,r.R)(),...e.components};return i?(0,a.jsx)(i,{...e,children:(0,a.jsx)(h,{...e})}):h(e)}}}]);